import React, { useState, useEffect } from 'react';
import api from '../../services/api';

const MenuPage = () => {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editingProduct, setEditingProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const [form, setForm] = useState({
    name: '', description: '', history: '', ingredients: '',
    price: '', cost: '', category_id: '', preparation_time_min: 15,
    image_url: '', model_3d_url: '', is_available: true,
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    setError('');
    try {
      const res = await api.get('/menu/SUC-001');
      if (res.data.status) {
        const cats = res.data.data.categories || [];
        setCategories(cats);
        const all = [];
        cats.forEach(c => {
          (c.products || []).forEach(p => {
            all.push({ ...p, categoryName: c.name });
          });
        });
        setProducts(all);
      } else {
        setError(res.data.message || 'Error del servidor');
      }
    } catch (err) {
      console.error(err);
      setError('No se pudo cargar el menú. Verifica que Laravel esté corriendo.');
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setForm({ name: '', description: '', history: '', ingredients: '', price: '', cost: '', category_id: '', preparation_time_min: 15, image_url: '', model_3d_url: '', is_available: true });
    setEditingProduct(null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const data = { ...form, branch_id: 1 };
      if (editingProduct) {
        await api.put(`/products/${editingProduct.id}`, data);
      } else {
        await api.post('/products', data);
      }
      setShowForm(false);
      resetForm();
      fetchData();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al guardar');
    }
  };

  const toggleAvailability = async (id, current) => {
    try {
      await api.put(`/products/${id}`, { is_available: !current });
      fetchData();
    } catch (err) {
      alert('Error al actualizar');
    }
  };

  const deleteProduct = async (id) => {
    if (!window.confirm('¿Eliminar este producto?')) return;
    try {
      await api.delete(`/products/${id}`);
      fetchData();
    } catch (err) {
      alert('Error al eliminar');
    }
  };

  const startEdit = (product) => {
    setEditingProduct(product);
    setForm({
      name: product.name || '',
      description: product.description || '',
      history: product.history || '',
      ingredients: product.ingredients || '',
      price: product.price || '',
      cost: product.cost || '',
      category_id: product.category_id || '',
      preparation_time_min: product.preparation_time_min || 15,
      image_url: product.image_url || '',
      model_3d_url: product.model_3d_url || '',
      is_available: product.is_available !== false,
    });
    setShowForm(true);
  };

  if (loading) return <p style={{ color: '#94a3b8', textAlign: 'center', padding: 50 }}>Cargando...</p>;

  if (error) return (
    <div>
      <h1 style={{ color: '#e2e8f0', fontSize: 28, marginBottom: 24 }}>🍽️ Gestionar Menú</h1>
      <div className="card" style={{ textAlign: 'center', padding: 40 }}>
        <p style={{ color: '#ef4444', marginBottom: 16 }}>{error}</p>
        <button onClick={fetchData} className="btn btn-primary">Reintentar</button>
      </div>
    </div>
  );

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
        <h1 style={{ color: '#e2e8f0', fontSize: 28 }}>🍽️ Gestionar Menú</h1>
        <button onClick={() => { resetForm(); setShowForm(!showForm); }} className="btn btn-primary">
          {showForm ? 'Cancelar' : '+ Nuevo Plato'}
        </button>
      </div>

      {showForm && (
        <div className="card" style={{ marginBottom: 24 }}>
          <h3 style={{ color: '#e2e8f0', marginBottom: 16 }}>
            {editingProduct ? '✏️ Editar Producto' : 'Crear Producto'}
          </h3>
          <form onSubmit={handleSubmit} style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 12 }}>
            <input type="text" placeholder="Nombre *" className="input" value={form.name} onChange={e => setForm({...form, name: e.target.value})} required />
            <select className="input" value={form.category_id} onChange={e => setForm({...form, category_id: e.target.value})} required>
              <option value="">Categoría *</option>
              {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
            <input type="number" step="0.01" placeholder="Precio *" className="input" value={form.price} onChange={e => setForm({...form, price: e.target.value})} required />
            <input type="number" step="0.01" placeholder="Costo" className="input" value={form.cost} onChange={e => setForm({...form, cost: e.target.value})} />
            <input type="number" placeholder="Tiempo (min)" className="input" value={form.preparation_time_min} onChange={e => setForm({...form, preparation_time_min: e.target.value})} />
            <input type="text" placeholder="URL imagen" className="input" value={form.image_url} onChange={e => setForm({...form, image_url: e.target.value})} />
            <input type="text" placeholder="URL modelo 3D (AR)" className="input" value={form.model_3d_url} onChange={e => setForm({...form, model_3d_url: e.target.value})} />
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <input type="checkbox" id="avail" checked={form.is_available} onChange={e => setForm({...form, is_available: e.target.checked})} style={{ width: 18, height: 18 }} />
              <label htmlFor="avail" style={{ color: '#e2e8f0', fontSize: 14 }}>Disponible</label>
            </div>
            <textarea placeholder="Descripción" className="input" value={form.description} onChange={e => setForm({...form, description: e.target.value})} style={{ gridColumn: 'span 2', minHeight: 60 }} />
            <textarea placeholder="Historia" className="input" value={form.history} onChange={e => setForm({...form, history: e.target.value})} style={{ gridColumn: 'span 2', minHeight: 60 }} />
            <textarea placeholder="Ingredientes" className="input" value={form.ingredients} onChange={e => setForm({...form, ingredients: e.target.value})} style={{ gridColumn: 'span 2', minHeight: 60 }} />
            <button type="submit" className="btn btn-success" style={{ gridColumn: 'span 2' }}>
              {editingProduct ? '💾 Guardar Cambios' : 'Crear Plato'}
            </button>
          </form>
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 16 }}>
        {products.map(product => (
          <div key={product.id} className="card">
            <div style={{ width: '100%', height: 140, borderRadius: 10, background: product.image_url ? `url(${product.image_url}) center/cover` : '#334155', marginBottom: 12, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 40 }}>
              {!product.image_url && '🍽️'}
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}>
              <h4 style={{ color: '#e2e8f0', fontSize: 15 }}>{product.name}</h4>
              <span style={{ color: '#fbbf24', fontWeight: 700 }}>${product.price?.toFixed(2)}</span>
            </div>
            <p style={{ color: '#94a3b8', fontSize: 12, marginBottom: 10 }}>{product.categoryName}</p>
            <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
              <button onClick={() => toggleAvailability(product.id, product.is_available)} style={{ padding: '5px 10px', borderRadius: 6, border: 'none', background: product.is_available ? 'rgba(16,185,129,0.1)' : 'rgba(239,68,68,0.1)', color: product.is_available ? '#10b981' : '#ef4444', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}>
                {product.is_available ? '✓ Disponible' : '✗ No disponible'}
              </button>
              <button onClick={() => startEdit(product)} style={{ padding: '5px 10px', borderRadius: 6, border: 'none', background: 'rgba(56,189,248,0.1)', color: '#38bdf8', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}>✏️ Editar</button>
              <button onClick={() => deleteProduct(product.id)} style={{ padding: '5px 10px', borderRadius: 6, border: 'none', background: 'rgba(239,68,68,0.1)', color: '#ef4444', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}>🗑️ Eliminar</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MenuPage;
